USE ThiTracNghiem;
GO
SET XACT_ABORT ON;
BEGIN TRANSACTION;

IF COL_LENGTH('HocVien','TinhTrangCha') IS NULL EXEC(N'ALTER TABLE HocVien ADD TinhTrangCha nvarchar(30) NULL');
IF COL_LENGTH('HocVien','TinhTrangMe') IS NULL EXEC(N'ALTER TABLE HocVien ADD TinhTrangMe nvarchar(30) NULL');
IF COL_LENGTH('GiaoVien','TinhTrangCha') IS NULL EXEC(N'ALTER TABLE GiaoVien ADD TinhTrangCha nvarchar(30) NULL');
IF COL_LENGTH('GiaoVien','TinhTrangMe') IS NULL EXEC(N'ALTER TABLE GiaoVien ADD TinhTrangMe nvarchar(30) NULL');

EXEC(N'UPDATE HocVien SET TinhTrangCha=CASE WHEN NULLIF(LTRIM(RTRIM(HoTenCha)),N'''') IS NOT NULL OR NULLIF(LTRIM(RTRIM(SdtCha)),N'''') IS NOT NULL THEN N''Còn sống'' ELSE N''Không rõ thông tin'' END WHERE TinhTrangCha IS NULL OR LTRIM(RTRIM(TinhTrangCha))=N''''');
EXEC(N'UPDATE HocVien SET TinhTrangMe=CASE WHEN NULLIF(LTRIM(RTRIM(HoTenMe)),N'''') IS NOT NULL OR NULLIF(LTRIM(RTRIM(SdtMe)),N'''') IS NOT NULL THEN N''Còn sống'' ELSE N''Không rõ thông tin'' END WHERE TinhTrangMe IS NULL OR LTRIM(RTRIM(TinhTrangMe))=N''''');
EXEC(N'UPDATE GiaoVien SET TinhTrangCha=CASE WHEN NULLIF(LTRIM(RTRIM(HoTenCha)),N'''') IS NOT NULL OR NULLIF(LTRIM(RTRIM(SdtCha)),N'''') IS NOT NULL THEN N''Còn sống'' ELSE N''Không rõ thông tin'' END WHERE TinhTrangCha IS NULL OR LTRIM(RTRIM(TinhTrangCha))=N''''');
EXEC(N'UPDATE GiaoVien SET TinhTrangMe=CASE WHEN NULLIF(LTRIM(RTRIM(HoTenMe)),N'''') IS NOT NULL OR NULLIF(LTRIM(RTRIM(SdtMe)),N'''') IS NOT NULL THEN N''Còn sống'' ELSE N''Không rõ thông tin'' END WHERE TinhTrangMe IS NULL OR LTRIM(RTRIM(TinhTrangMe))=N''''');

-- Dùng NCHAR để migration chạy đúng cả khi sqlcmd đọc file theo code page Windows.
DECLARE @Alive nvarchar(30)=NCHAR(67)+NCHAR(242)+NCHAR(110)+NCHAR(32)+NCHAR(115)+NCHAR(7889)+NCHAR(110)+NCHAR(103);
DECLARE @Deceased nvarchar(30)=NCHAR(272)+NCHAR(227)+NCHAR(32)+NCHAR(109)+NCHAR(7845)+NCHAR(116);
DECLARE @Unknown nvarchar(30)=NCHAR(75)+NCHAR(104)+NCHAR(244)+NCHAR(110)+NCHAR(103)+NCHAR(32)+NCHAR(114)+NCHAR(245)+NCHAR(32)+NCHAR(116)+NCHAR(104)+NCHAR(244)+NCHAR(110)+NCHAR(103)+NCHAR(32)+NCHAR(116)+NCHAR(105)+NCHAR(110);
UPDATE HocVien SET TinhTrangCha=CASE WHEN NULLIF(LTRIM(RTRIM(HoTenCha)),N'') IS NOT NULL OR NULLIF(LTRIM(RTRIM(SdtCha)),N'') IS NOT NULL THEN @Alive ELSE @Unknown END WHERE TinhTrangCha NOT IN(@Alive,@Deceased,@Unknown);
UPDATE HocVien SET TinhTrangMe=CASE WHEN NULLIF(LTRIM(RTRIM(HoTenMe)),N'') IS NOT NULL OR NULLIF(LTRIM(RTRIM(SdtMe)),N'') IS NOT NULL THEN @Alive ELSE @Unknown END WHERE TinhTrangMe NOT IN(@Alive,@Deceased,@Unknown);
UPDATE GiaoVien SET TinhTrangCha=CASE WHEN NULLIF(LTRIM(RTRIM(HoTenCha)),N'') IS NOT NULL OR NULLIF(LTRIM(RTRIM(SdtCha)),N'') IS NOT NULL THEN @Alive ELSE @Unknown END WHERE TinhTrangCha NOT IN(@Alive,@Deceased,@Unknown);
UPDATE GiaoVien SET TinhTrangMe=CASE WHEN NULLIF(LTRIM(RTRIM(HoTenMe)),N'') IS NOT NULL OR NULLIF(LTRIM(RTRIM(SdtMe)),N'') IS NOT NULL THEN @Alive ELSE @Unknown END WHERE TinhTrangMe NOT IN(@Alive,@Deceased,@Unknown);

ALTER TABLE HocVien ALTER COLUMN TinhTrangCha nvarchar(30) NOT NULL;
ALTER TABLE HocVien ALTER COLUMN TinhTrangMe nvarchar(30) NOT NULL;
ALTER TABLE GiaoVien ALTER COLUMN TinhTrangCha nvarchar(30) NOT NULL;
ALTER TABLE GiaoVien ALTER COLUMN TinhTrangMe nvarchar(30) NOT NULL;

IF EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID('HocVien') AND name='DF_HocVien_TinhTrangCha') ALTER TABLE HocVien DROP CONSTRAINT DF_HocVien_TinhTrangCha;
IF EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID('HocVien') AND name='DF_HocVien_TinhTrangMe') ALTER TABLE HocVien DROP CONSTRAINT DF_HocVien_TinhTrangMe;
IF EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID('GiaoVien') AND name='DF_GiaoVien_TinhTrangCha') ALTER TABLE GiaoVien DROP CONSTRAINT DF_GiaoVien_TinhTrangCha;
IF EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID('GiaoVien') AND name='DF_GiaoVien_TinhTrangMe') ALTER TABLE GiaoVien DROP CONSTRAINT DF_GiaoVien_TinhTrangMe;
ALTER TABLE HocVien ADD CONSTRAINT DF_HocVien_TinhTrangCha DEFAULT (NCHAR(75)+NCHAR(104)+NCHAR(244)+NCHAR(110)+NCHAR(103)+NCHAR(32)+NCHAR(114)+NCHAR(245)+NCHAR(32)+NCHAR(116)+NCHAR(104)+NCHAR(244)+NCHAR(110)+NCHAR(103)+NCHAR(32)+NCHAR(116)+NCHAR(105)+NCHAR(110)) FOR TinhTrangCha;
ALTER TABLE HocVien ADD CONSTRAINT DF_HocVien_TinhTrangMe DEFAULT (NCHAR(75)+NCHAR(104)+NCHAR(244)+NCHAR(110)+NCHAR(103)+NCHAR(32)+NCHAR(114)+NCHAR(245)+NCHAR(32)+NCHAR(116)+NCHAR(104)+NCHAR(244)+NCHAR(110)+NCHAR(103)+NCHAR(32)+NCHAR(116)+NCHAR(105)+NCHAR(110)) FOR TinhTrangMe;
ALTER TABLE GiaoVien ADD CONSTRAINT DF_GiaoVien_TinhTrangCha DEFAULT (NCHAR(75)+NCHAR(104)+NCHAR(244)+NCHAR(110)+NCHAR(103)+NCHAR(32)+NCHAR(114)+NCHAR(245)+NCHAR(32)+NCHAR(116)+NCHAR(104)+NCHAR(244)+NCHAR(110)+NCHAR(103)+NCHAR(32)+NCHAR(116)+NCHAR(105)+NCHAR(110)) FOR TinhTrangCha;
ALTER TABLE GiaoVien ADD CONSTRAINT DF_GiaoVien_TinhTrangMe DEFAULT (NCHAR(75)+NCHAR(104)+NCHAR(244)+NCHAR(110)+NCHAR(103)+NCHAR(32)+NCHAR(114)+NCHAR(245)+NCHAR(32)+NCHAR(116)+NCHAR(104)+NCHAR(244)+NCHAR(110)+NCHAR(103)+NCHAR(32)+NCHAR(116)+NCHAR(105)+NCHAR(110)) FOR TinhTrangMe;

COMMIT;
GO
